function arrAmount(localHammer,cap){const tiers=[[50000,.04],[200000,.03],[350000,.01],[500000,.005],[Infinity,.0025]];let prev=0,r=0;for(const [c,rate] of tiers){const slice=Math.max(0,Math.min(localHammer,c)-prev);r+=slice*rate;prev=c;if(localHammer<=c)break;}return Math.min(r,cap);}
