  const salesTax=(p.venue==='ny'&&p.dest==='nyc')?price*V.salesTax:0;const useTax=(p.venue!=='ny'&&p.dest==='nyc')?price*D.useTax:0;
  const destVat=(D.impVat&&V.country!==D.country)?price*D.impVat:0; /* a destination's import VAT applies unless the sale room is already in that country */
  /* the resale right: the room must have it, the work must qualify (the artist's term and nationality when the deal comes from a lot, else the
     box), and the hammer must reach the room's threshold; the house charges it to whoever its conditions name (arrPayer) */
  const arrOn=!!V.arr&&(p.artist?arrApplies(p.artist,+TODAY.slice(0,4),p.venue):!!p.living);
  const arr=arrOn&&H/fxv>=(V.arrMin||0)?arrAmount(H/fxv,V.arrCap)*fxv:0;const arrSeller=V.arrPayer==='seller'?arr:0,arrBuyer=arr-arrSeller;
  const sc=p.seller==='5'?.05:p.seller==='10'?.10:0;const commission=H*sc;const bonus=p.seller==='105'?H*.05:p.seller==='109'?H*.09:0;
