  const c1=[['hammer','Hammer price',m.H,'var(--c1)'],['prem','Buyer’s premium',m.prem,'var(--c2)'],['tax','Taxes',m.taxes,'var(--c3)'],['arr','Resale royalty',m.arrBuyer,'var(--verd)'],['ship','Shipping & insurance',m.ship,'var(--cx)']].filter(n=>n[2]>0);
  const links=[['hammer','seller',m.H-m.commission-m.arrSeller,'var(--c1)','Hammer less the seller’s commission'],['hammer','house',ch,'var(--c1)','Seller’s commission'],['hammer','seller',cb,'var(--c1)','Enhanced hammer beyond the premium, from the commission'],['hammer','guar',cf,'var(--c1)','Guarantor’s fee beyond the premium, from the commission'],['hammer','estate',m.arrSeller,'var(--c1)','Resale royalty, deducted from the seller'],['prem','house',ph,'var(--c2)','Premium kept by the house'],['prem','guar',pf,'var(--c2)','Guarantor’s fee, paid from the premium'],['prem','seller',pb,'var(--c2)','Enhanced hammer: part of the premium passed to the seller'],['tax','treas',m.taxes,'var(--c3)','Sales or use tax, VAT, import VAT'],['arr','estate',m.arrBuyer,'var(--verd)','Resale royalty, paid by the buyer'],['ship','shipper',m.ship,'var(--cx)','Crating, transit and transit insurance']].filter(l=>l[2]>0.005);
