  const c2=[['seller','Seller'],['house','Auction house'],['guar','Guarantor'],['treas','Treasury'],['estate','Artist or estate'],['shipper','Shipper & insurer']].map(n=>[n[0],n[1],into(n[0])]).filter(n=>n[2]>0.005);
  const total=m.buyer;const H=Math.max(330,Math.max(c1.length,c2.length)*(LB+pad)+40);const k=(H-40-pad*Math.max(c1.length,c2.length))/total;const hgt=v=>Math.max(2,v*k);
  const stack=(col,x)=>{const pos={};let y=0;col.forEach(n=>{const h=hgt(n[2]);pos[n[0]]={x,y,h,slot:Math.max(h,LB),used:0,name:n[1],v:n[2],col:n[3]||'var(--ink2)'};y+=Math.max(h,LB)+pad;});const off=(H-(y-pad))/2;Object.values(pos).forEach(p=>p.y+=off);return pos;};
