  let paths='';c1.forEach(n=>{const t=pos[n[0]];const w=hgt(n[2]);paths+=band(x0+NW,by+bused,x1,t.y,w,n[3],`${n[1]}: ${fmtUSD(n[2])}`);bused+=w;});
  links.forEach(l=>{const s=pos[l[0]],t=pos[l[1]];if(!s||!t)return;const w=hgt(l[2]);paths+=band(x1+NW,s.y+s.used,x2,t.y+t.used,w,l[3],`${l[4]}: ${fmtUSD(l[2])}`);s.used+=w;t.used+=w;});
  const node=(x,p,label,amt)=>`<rect x="${x}" y="${p.y.toFixed(1)}" width="${NW}" height="${p.h.toFixed(1)}" fill="${p.col}" rx="1"/><text x="${x+NW+8}" y="${(p.y+13).toFixed(1)}" class="lbl">${esc(label)}</text><text x="${x+NW+8}" y="${(p.y+29).toFixed(1)}" class="amt">${esc(amt)}</text>`;
  let nodes=`<rect x="${x0}" y="${by.toFixed(1)}" width="${NW}" height="${bh.toFixed(1)}" fill="var(--ink)" rx="1"/><text x="${x0}" y="${Math.max(14,by-26).toFixed(1)}" class="lbl">Buyer pays</text><text x="${x0}" y="${Math.max(34,by-6).toFixed(1)}" class="amt big">${esc(fmtUSD(total))}</text>`;
  c1.forEach(n=>{const p=pos[n[0]];nodes+=node(x1,p,n[1],fmtUSD(n[2]));});c2.forEach(n=>{const p=pos[n[0]];nodes+=node(x2,p,n[1],fmtUSD(n[2]));});
