  FLOW.house=$('#fhouse').value;FLOW.venue=$('#fvenue').value;FLOW.structure=$('#fstruct').value;FLOW.seller=$('#fseller').value;FLOW.dest=$('#fdest').value;FLOW.loan=$('#floan').value;FLOW.imported=$('#fimported').checked;
