function flowScenario(m){const st={none:'no guarantee',house:'a house guarantee',third:`a third-party guarantee at ${Math.round(FLOW.guar*100)}% of the hammer, fee ${Math.round(FLOW.feeShare*100)}% of the overage`}[FLOW.structure]||'';const sd=`seller’s deal: ${(FLOW_SELLER[FLOW.seller]||'').toLowerCase()}`;const ln=`financing: ${(FLOW_LOAN[FLOW.loan]||'').toLowerCase()}`;
  return `Hammer ${fmtUSD(m.H)} at ${houseName(m.sched)}, ${m.V.n}; ${st}; ${sd}; destination: ${m.D.n}; ${ln}${FLOW.artist?`; artist: ${FLOW.artist}`:''}${m.arrOn?'; the resale right applies':''}${FLOW.imported?'; an imported lot':''}.`;}
const flowFX=()=>`£1 = $${FX.gbp}, €1 = $${FX.eur}, CHF 1 = $${FX.chf}, HK$1 = $${FX.hkd}`;
/* the ledger as text: what a buyer forwards to a lawyer or a family office */
function flowLedgerText(){const m=flowModel(FLOW);const L=[`Follow the money, Subhasta (${fdate(TODAY)})`,flowScenario(m),`Buyer’s all-in ${fmtUSD(m.buyer)} (${(m.buyer/m.H*100-100).toFixed(1)}% above the hammer) · seller receives ${fmtUSD(m.seller)} · house keeps ${fmtUSD(m.house)} · resale at break-even ${fmtUSD(m.breakEven)}`,''];
  flowRows(m).forEach(r=>L.push(r[1]?`${r[0]}: ${fmtUSD(r[1])}. ${r[2]}`:/^(?:None|Not charged|No )/.test(r[2])?`${r[0]}: ${r[2]}`:`${r[0]}: none. ${r[2]}`));L.push('',`FX: ${flowFX()}. Premium tiers are the houses’ 2026 schedules; each other line follows the rule in the atlas entry named in the terminal.`);return L.join('\n');}
/* the ledger as CSV: amounts as plain dollars for a spreadsheet, each line with its atlas entry and deep link, then the totals and the assumptions */
function flowLedgerCSV(){const m=flowModel(FLOW),base=location.href.split('#')[0];const out=[['Line','Amount (US$)','Rule','Atlas entry','Link']];
  flowRows(m).forEach(r=>{const a=r[3]!=='fees'&&r[3]!=='rule'?ATL(r[3]):null;out.push([r[0],Math.round(r[1]||0),r[2],r[3]==='fees'?'Buyer’s premium in force (Lexicon)':a?a.t:'',a?base+'#under-'+a.id:'']);});
  out.push([],['Total','Amount (US$)'],['Buyer’s all-in',Math.round(m.buyer)],['Seller receives',Math.round(m.seller)],['House keeps',Math.round(m.house)],['Resale hammer at break-even',Math.round(m.breakEven)]);
  out.push([],['Assumption','Value'],['Hammer (US$)',Math.round(m.H)],['House',houseName(m.sched)],['Sale room',m.V.n],['Structure',{none:'No guarantee',house:'House guarantee',third:'Third-party guarantee'}[FLOW.structure]||''],['Guarantee, % of hammer',FLOW.structure==='third'?Math.round(FLOW.guar*100):''],['Guarantor’s fee, % of the overage',FLOW.structure==='third'?Math.round(FLOW.feeShare*100):''],['Seller’s deal',FLOW_SELLER[FLOW.seller]||FLOW.seller],['Destination',m.D.n],['Financing',FLOW_LOAN[FLOW.loan]||FLOW.loan],['Artist (sets the resale right room by room)',FLOW.artist||''],['Resale right applies',m.arrOn?'yes':'no'],['Imported lot',FLOW.imported?'yes':'no'],['Shipping & transit insurance (US$)',Math.round(FLOW.ship||0)],['FX',flowFX()],['As of',TODAY]);
  return rowsCSV(out);}
/* the same deal at five hammers: what the buyer pays and the seller nets if the room runs cold or hot */
const FLOW_STEPS=[-.2,-.1,0,.1,.2];
/* a third-party guarantee is fixed in dollars before the sale: below it the irrevocable bidder buys the work at the bid, and above it the
   guarantor's fee grows with the overage while the house's share of the premium shrinks */
function flowSensitivity(){const G0=FLOW.structure==='third'?FLOW.guar*FLOW.hammer:0;
  const cols=FLOW_STEPS.map(d=>{const h=FLOW.hammer*(1+d),won=G0>0&&h<G0-0.5,H=won?G0:h;return {d,won,m:flowModel(Object.assign({},FLOW,{hammer:H},G0?{guar:G0/H}:{}))};});
  const hd=c=>(c.d===0?'as set':`${c.d>0?'+':'−'}${Math.round(Math.abs(c.d)*100)}%`)+(c.won?'<span class="fmx-sub">the guarantor buys at the bid</span>':'');const cell=(c,v,cls)=>`<td class="n${cls?' '+cls:''}${c.d===0?' cur':''}">${fmtUSD(v)}</td>`;
  return `<table class="tbl sens"><caption class="sr">The same deal at five hammer prices</caption><thead><tr><th scope="col">If the bidding reaches</th>${cols.map(c=>`<th scope="col" class="n${c.d===0?' cur':''}">${hd(c)}</th>`).join('')}</tr></thead><tbody>
    <tr><th scope="row">Hammer</th>${cols.map(c=>cell(c,c.m.H)).join('')}</tr><tr><th scope="row">Buyer’s all-in</th>${cols.map(c=>cell(c,c.m.buyer,'money')).join('')}</tr><tr><th scope="row">Seller receives</th>${cols.map(c=>cell(c,c.m.seller)).join('')}</tr><tr><th scope="row">House keeps</th>${cols.map(c=>cell(c,c.m.house)).join('')}</tr>${G0?`<tr><th scope="row">Guarantor’s fee</th>${cols.map(c=>cell(c,c.m.fee)).join('')}</tr>`:''}</tbody></table>`;}
/* the same purchase kept in each destination: the tax that arrival triggers, storage, and the first year in all */
function flowDestinations(){const yr1=x=>x.buyer+x.storage+x.ins+x.interest;const rows=Object.keys(DESTS).map(d=>[d,flowModel(Object.assign({},FLOW,{dest:d}))]);
  /* a deferred tax is not a saving: a destination marked defer is shown but never called the cheapest */
  const low=Math.min(...rows.filter(r=>!DESTS[r[0]].defer).map(r=>Math.round(yr1(r[1]))));
  return `<table class="tbl"><thead><tr><th scope="col">Same purchase, ${words(rows.length)} places to keep it</th><th scope="col" class="n">VAT in the room</th><th scope="col" class="n">Tax on arrival</th><th scope="col" class="n">Storage, year one</th><th scope="col" class="n">Buyer’s all-in</th><th scope="col" class="n">First year in all</th></tr></thead><tbody>${rows.map(([d,x])=>{const t=x.salesTax+x.useTax+x.destVat,vr=x.vatPrem+x.impVat;return `<tr class="${d===FLOW.dest?'cur':''}"><td><b>${esc(DESTS[d].n)}</b>${!DESTS[d].defer&&Math.round(yr1(x))===low?' <span class="tag rec">cheapest first year</span>':''}${DESTS[d].defer?' <span class="tag">tax deferred, not ranked</span>':''}${d===FLOW.dest?' <span class="tag">selected</span>':''}</td><td class="n">${vr?fmtUSD(vr):'—'}</td><td class="n">${t?fmtUSD(t):'—'}</td><td class="n">${x.storage?fmtUSD(x.storage):'—'}</td><td class="n money">${fmtUSD(x.buyer)}</td><td class="n">${fmtUSD(yr1(x))}</td></tr>`;}).join('')}</tbody></table><div class="note" style="margin-top:8px">The sale room stays ${esc(VENUES[FLOW.venue].n)}; only the destination changes. VAT in the room is its VAT on the premium and an imported lot’s import VAT; both come back when the work leaves the country or goes into bond, against proof of export. Tax on arrival is New York sales or use tax, or the destination’s import VAT. The first year adds storage, insurance at ${(FLOW.ins*100).toFixed(1)}% of the price (none on a museum loan) and any loan interest to the buyer’s all-in. A museum loan defers the use tax rather than removing it, so it is shown but not ranked.</div>`;}
/* every sale room against every destination for the same hammer, house and settings: the first year in all (buyer's all-in, storage,
   insurance, loan interest). The cheapest cell and the case on screen are marked; the reading says what the cheapest route saves. */
function flowMatrix(){const yr1=x=>x.buyer+x.storage+x.ins+x.interest;const R=Object.keys(VENUES),D=Object.keys(DESTS);
  const M=R.map(v=>D.map(d=>yr1(flowModel(Object.assign({},FLOW,{venue:v,dest:d})))));
  /* a deferred tax is not a saving: a destination marked defer (the museum loan) is shown but kept out of the ranking, the minimum and the shading */
  const rk=j=>!DESTS[D[j]].defer;const flat=[];M.forEach(row=>row.forEach((c,j)=>{if(rk(j))flat.push(c);}));const min=Math.min(...flat),max=Math.max(...flat);
  const best=(i,j)=>rk(j)&&M[i][j]-min<1;   /* within a dollar of the cheapest: a tie */
  const ci=R.indexOf(FLOW.venue),cj=D.indexOf(FLOW.dest),cur=ci>=0&&cj>=0?M[ci][cj]:null;
  const sh=d=>DESTS[d].s||DESTS[d].n;const act=d=>DESTS[d].act||`keeping it in ${sh(d)}`;
  const ties=[];M.forEach((row,i)=>row.forEach((c,j)=>{if(best(i,j))ties.push([i,j]);}));const route=([i,j])=>`${VENUES[R[i]].n} to ${sh(D[j])}`;
  const first=ties.length===1?`buying in ${esc(VENUES[R[ties[0][0]]].n)} and ${esc(act(D[ties[0][1]]))}`:`by ${words(ties.length)} routes: ${esc(ties.slice(0,4).map(route).join('; '))}${ties.length>4?`; and ${words(ties.length-4)} more`:''}`;
  const onScreen=cur==null?'':`buying in ${VENUES[FLOW.venue].n} and ${act(FLOW.dest)}`;
  const here=cur==null?'':!rk(cj)?`The route on screen (${esc(onScreen)}) defers the use tax rather than saving it, so it is not ranked; `:best(ci,cj)?(ties.length===1?'The route on screen is the cheapest; ':`The route on screen is one of the ${words(ties.length)} cheapest; `):`The route on screen (${esc(onScreen)}) costs ${esc(fmtUSD(cur-min))} more; `;
  const dear=`the dearest costs ${esc(fmtUSD(max-min))} more.`;
  const read=`For a ${esc(fmtUSD(FLOW.hammer))} hammer at ${esc(houseName(FLOW.house))} the cheapest first year in all is <b>${esc(fmtUSD(min))}</b>, ${first}. ${here?here+dear:dear.charAt(0).toUpperCase()+dear.slice(1)} Each cell is the extra first-year cost against the cheapest.`;
  const signed=v=>(v<0?'−':'+')+esc(fmtUSD(Math.abs(v)));
  return `<p class="note fmx-read">${read}</p><div class="tblwrap"><table class="tbl fmx" id="fmx" data-min="${Math.round(min)}"><caption class="sr">The first year in all for every sale room and every destination, against the cheapest</caption><thead><tr><th scope="col" class="hxy" aria-label="Bought in, kept in"><span class="hx">Bought in ↓</span><span class="hs"> · </span><span class="hx">kept in →</span></th>${D.map((d,j)=>`<th scope="col" class="n${rk(j)?'':' defer'}">${esc(sh(d))}${rk(j)?'':'<span class="fmx-sub">tax deferred</span>'}</th>`).join('')}</tr></thead><tbody>${R.map((v,i)=>`<tr><th scope="row">${esc(VENUES[v].n)}</th>${D.map((d,j)=>{const c=M[i][j],dd=c-min;const w=rk(j)&&max>min?dd/(max-min):0;return `<td class="n${best(i,j)?' best':''}${rk(j)?'':' defer'}${i===ci&&j===cj?' cur':''}" data-v="${Math.round(c)}" style="--w:${Math.max(0,w).toFixed(3)}" title="Bought in ${esc(VENUES[v].n)}, ${esc(act(d))}: ${esc(fmtUSD(c))} in the first year">${best(i,j)?'lowest':signed(dd)}</td>`;}).join('')}</tr>`).join('')}</tbody></table></div><div class="note" style="margin-top:8px">The same hammer, house, structure, seller’s deal, shipping, insurance and financing in every cell; each room’s premium, VAT and resale right, and each destination’s tax on arrival and storage, are the ones in the ledger above. A work that leaves the room’s country, or goes into bond, has the room’s VAT refunded against proof of export. The museum loan is shown but not ranked: the museum insures, and the use tax is deferred, not removed. The cheapest routes are outlined in gilt; the route on screen is underlined.</div>`;}
/* the two headline amounts in the room's currency and in the destination's, at the FX the model uses */
function flowLocalMoney(m){const FXK={london:'gbp',paris:'eur',geneva:'chf',hk:'hkd'},BYC={UK:'gbp',FR:'eur',CH:'chf',HK:'hkd'},SYM={gbp:'£',eur:'€',chf:'CHF ',hkd:'HK$'};
  const inCur=(usd,k)=>{const v=usd/FX[k];return SYM[k]+(v>=1e6?(v/1e6).toFixed(2)+'m':Math.round(v).toLocaleString('en-US'));};const k1=FXK[FLOW.venue]&&FX[FXK[FLOW.venue]]?FXK[FLOW.venue]:null,k2=BYC[m.D.country]&&FX[BYC[m.D.country]]?BYC[m.D.country]:null;
  if(!k1&&!k2)return '';const parts=[];if(k1)parts.push(`${inCur(m.buyer,k1)} in the room’s currency`);if(k2&&k2!==k1)parts.push(`${inCur(m.buyer,k2)} in the destination’s`);
  return `In local money: the buyer’s all-in is ${parts.join(' or ')}${k1?`; the seller receives ${inCur(m.seller,k1)}`:''}. At ${flowFX()}.`;}
function drawFlow(){const m=flowModel(FLOW);$('#fhv').textContent=fmtUSD(FLOW.hammer);const sub=flowSubsidy(m);$('#fsank').innerHTML=sankeySVG(m)+(sub?`<p class="note">The guarantor’s fee and the enhanced hammer exceed the house’s premium and commission by ${esc(fmtUSD(sub))}: the house pays that from its own funds, outside the buyer’s money drawn here.</p>`:'');bindTips($('#fsank'));
  const fl=$('#fliving');if(fl&&FLOW.artist)fl.checked=m.arrOn;const fa=$('#farr');if(fa)fa.textContent=flowArrNote();
  const pct=v=>m.H?`${(v/m.H*100).toFixed(1)}% of hammer`:'';
  $('#fkpi').innerHTML=`<div class="kpi kfix"><div class="l">Buyer’s all-in</div><div class="v">${fmtUSD(m.buyer)}</div><div class="d">${(m.buyer/m.H*100-100).toFixed(1)}% above the hammer: premium, taxes, royalty and shipping</div></div><div class="kpi kfix"><div class="l">Seller receives</div><div class="v">${fmtUSD(m.seller)}</div><div class="d">${m.bonus?'enhanced hammer':m.commission?`less ${FLOW.seller}% commission`:'no commission'}${m.arrSeller?', less royalty':''}</div></div><div class="kpi kfix"><div class="l">House keeps</div><div class="v">${fmtUSD(m.house)}</div><div class="d">${pct(m.house)}${m.fee?', after the guarantor’s fee':''}${m.house<0?'; it pays to win the consignment':''}</div></div><div class="kpi kfix"><div class="l">To resell at break-even</div><div class="v">${m.H?`+${((m.breakEven/m.H-1)*100).toFixed(0)}%`:'—'}</div><div class="d">the next hammer must reach ${fmtUSD(m.breakEven)} to recover the all-in after a 5% commission; holding costs are in the Lab’s round trip</div></div>`;
  const rows=flowRows(m);
  bindTips($('#fkpi'));$('#fledger').innerHTML=`<table class="tbl"><thead><tr><th>Line</th><th class="n">Amount</th><th>Rule</th><th><span class="sr">Source</span></th></tr></thead><tbody>${rows.map(r=>`<tr class="${r[1]?'':'faint'}"><td>${esc(r[0])}</td><td class="n money">${r[1]?fmtUSD(r[1]):'—'}</td><td>${esc(r[2])}</td><td class="n">${r[3]==='fees'?`<button class="lnk" data-go="lexicon">schedule</button>`:r[3]==='rule'?'':`<button class="lnk" data-under="${r[3]}">source</button>`}</td></tr>`).join('')}</tbody></table><div class="note" style="margin-top:10px">${esc(m.V.note)} ${esc(m.D.note)} FX assumptions: ${esc(flowFX())}. Marginal premium tiers are the houses’ 2026 schedules; everything else is the rule described in the atlas entry linked on each line. ${limLink('money','What this model leaves out')}</div>`;bindLinks($('#fledger'));bindUnderLinks($('#fledger'));
  $('#fsens').innerHTML=flowSensitivity();$('#ffx').textContent=flowLocalMoney(m);$('#fdests').innerHTML=flowDestinations();const fmx=$('#fmatrix');if(fmx){fmx.innerHTML=flowMatrix();markScrollables(fmx);}
  const rows2=Object.keys(VENUES).map(v=>{const mm2=flowModel(Object.assign({},FLOW,{venue:v}));return [v,mm2];});const minB=Math.min(...rows2.map(r=>r[1].buyer)),isBest=x=>x.buyer-minB<1,nBest=rows2.filter(r=>isBest(r[1])).length;   /* rooms within a dollar of the cheapest tie */
  $('#fcompare').innerHTML=`<table class="tbl"><thead><tr><th>Same hammer, same buyer, five rooms</th><th class="n">Buyer’s all-in</th><th class="n">Seller nets</th><th class="n">House keeps</th><th class="n">Taxes</th><th class="n">Royalty</th></tr></thead><tbody>${rows2.map(([v,x])=>`<tr class="${v===FLOW.venue?'cur':''}"><td><b>${esc(VENUES[v].n)}</b>${isBest(x)?` <span class="tag rec">${nBest>1?'tied cheapest':'cheapest for the buyer'}</span>`:''}${v===FLOW.venue?' <span class="tag">selected</span>':''}</td><td class="n money">${fmtUSD(x.buyer)}</td><td class="n">${fmtUSD(x.seller)}</td><td class="n">${fmtUSD(x.house)}</td><td class="n">${fmtUSD(x.taxes)}</td><td class="n">${x.arr?fmtUSD(x.arr):'—'}</td></tr>`).join('')}</tbody></table><div class="note" style="margin-top:8px">The destination stays “${esc(m.D.n)}”; only the sale room changes, so the spread between rows is tax, VAT and royalty. The premium schedule is the same for every room here: the dollar tiers, where the houses’ local thresholds (£1.5m, €1.75m, HK$15m) differ by up to about $5,000 on a lot above $2m.</div>`;}
function initFlow(){$('#fctl').innerHTML=flowControls();const upd=e=>{readFlow(e&&e.target);drawFlow();};$$('#fctl input,#fctl select').forEach(el=>el.addEventListener('input',upd));$$('#fctl [data-preset]').forEach(b=>b.addEventListener('click',()=>{Object.assign(FLOW,{imported:false,loan:'none',feeShare:.2,guar:.85,ins:.002,artist:null,touched:true},PRESETS[+b.dataset.preset].p);initFlow();}));drawFlow();}

/* ---- journeys ---- */
function journeyCard(j){const m=IMG[j.img];const pts=j.steps.filter(s=>s.usd);let line='';if(pts.length>=2){const W=300,H=70;const ys=pts.map(p=>Math.log10(p.usd));const mn=Math.min(...ys),mx=Math.max(...ys);const X=i=>8+(i/(pts.length-1))*(W-16),Y=v=>H-8-((v-mn)/(mx-mn||1))*(H-16);line=`<svg viewBox="0 0 ${W} ${H}" class="jline" aria-hidden="true"><polyline points="${pts.map((p,i)=>`${X(i).toFixed(1)},${Y(Math.log10(p.usd)).toFixed(1)}`).join(' ')}" fill="none" stroke="var(--gilt)" stroke-width="1.6"/>${pts.map((p,i)=>`<circle cx="${X(i).toFixed(1)}" cy="${Y(Math.log10(p.usd)).toFixed(1)}" r="3" fill="var(--gilt)"/><text x="${X(i).toFixed(1)}" y="${(Y(Math.log10(p.usd))-7).toFixed(1)}" text-anchor="${i===0?'start':i===pts.length-1?'end':'middle'}">${esc(p.p.split(' ')[0])}</text>`).join('')}</svg>`;}
  /* a fall between the first and last prices reads as a percentage: 0.3× alone is easily misread */
  const mult=pts.length>=2?pts[pts.length-1].usd/pts[0].usd:null;
  return `<article class="journey" id="journey-${esc(j.id)}" tabindex="-1" aria-label="${esc(j.t)}"><a href="#" class="jpic" data-lb="${j.img}" style="background-color:${m?m.avg:'var(--paper)'}"><img src="img/t/${j.img}.jpg" alt="${esc(m?m.a+', '+m.t:j.t)}" loading="lazy" style="object-position:${m?m.fp:'50% 50%'}"></a><div class="jbody"><div class="jk">${esc(j.a)} ${vflag(j.v)}</div><h3>${esc(j.t)}</h3>${line}${mult?`<div class="jmult">${mult<1?`${Math.round((1-mult)*100)}% less at the last recorded price than at the first (${mult.toFixed(2)}×; log scale)`:`${mult>=100?Math.round(mult).toLocaleString('en-US'):mult.toFixed(1)}× between the first and last recorded prices (log scale)`}</div>`:''}<div class="jsteps">${j.steps.map(s=>`<div class="js"><span class="y">${esc(s.y)}</span><span class="w"><b>${esc(s.place)}</b>${s.place?' · ':''}${esc(s.who)}${s.note?` <i>(${esc(s.note)})</i>`:''}</span><span class="p money">${esc(s.p)}</span></div>`).join('')}</div><div class="jacts">${j.lot&&lotByTitle(j.lot)?`<button class="btn sm" data-lot="${esc(lotByTitle(j.lot).id)}">Open the lot</button>`:''}${j.src.map(s=>`<a class="btn sm" href="${esc(s[1])}" target="_blank" rel="noopener">${esc(s[0])}</a>`).join('')}</div><div class="jcredit">Pictured: ${esc(CREDIT(j.img))}</div></div></article>`;}

/* ---- the circuit ---- */
let stationSel='auction';
function ringSVG(){const W=820,H=600,cx=410,cy=300,R=232,RL=262;const n=STATIONS.length;
  const pt=(i,r)=>{const a=-Math.PI/2+i/n*Math.PI*2;return [cx+r*Math.cos(a),cy+r*Math.sin(a),a];};
  let s=`<svg viewBox="0 0 ${W} ${H}" class="ring" role="group" aria-label="The circuit of a work of art"><circle cx="${cx}" cy="${cy}" r="${R}" class="rg"/><circle cx="${cx}" cy="${cy}" r="${R}" class="rgd"/>`;
  s+=`<g class="arrows">${[0.08,0.33,0.58,0.83].map(f=>{const a=-Math.PI/2+f*Math.PI*2;const x=cx+R*Math.cos(a),y=cy+R*Math.sin(a);return `<path d="M-6,-5 L4,0 L-6,5 Z" transform="translate(${x.toFixed(1)},${y.toFixed(1)}) rotate(${(a*180/Math.PI+90).toFixed(1)})"/>`;}).join('')}</g>`;
  STATIONS.forEach((st,i)=>{const [x,y,a]=pt(i,R);const [lx,ly]=pt(i,RL);const cos=Math.cos(a);const anchor=cos>0.35?'start':cos<-0.35?'end':'middle';const dy=Math.sin(a)>0.9?14:Math.sin(a)<-0.9?-6:4;
    s+=`<g class="stn ${st.id===stationSel?'on':''}" data-station="${st.id}" tabindex="0" role="button" aria-label="${esc(st.n)}"><circle cx="${x.toFixed(1)}" cy="${y.toFixed(1)}" r="16" class="hit"/><circle cx="${x.toFixed(1)}" cy="${y.toFixed(1)}" r="7" class="dot"/><text x="${lx.toFixed(1)}" y="${(ly+dy).toFixed(1)}" text-anchor="${anchor}">${esc(st.n)}</text></g>`;});
  const sel=STATIONS.findIndex(x=>x.id===stationSel);const [sx,sy]=pt(sel,R);const st=STATIONS[sel];const m=st.img&&IMG[st.img]?IMG[st.img]:null;const MR=118;
  s+=`<line x1="${cx}" y1="${cy}" x2="${sx.toFixed(1)}" y2="${sy.toFixed(1)}" class="spoke"/><defs><clipPath id="ringclip"><circle cx="${cx}" cy="${cy}" r="${MR}"/></clipPath></defs>`;
  if(m)s+=`<g class="medal" data-lb="${st.img}" tabindex="0" role="button" aria-label="Enlarge the picture: ${esc(m.a)}, ${esc(m.t)}"><circle cx="${cx}" cy="${cy}" r="${MR+6}" class="mring"/><image href="img/${st.img}.jpg" x="${cx-MR}" y="${cy-MR}" width="${MR*2}" height="${MR*2}" preserveAspectRatio="xMidYMid slice" clip-path="url(#ringclip)"/><circle cx="${cx}" cy="${cy}" r="${MR}" class="mring2"/></g>`;else s+=`<g class="medal"><circle cx="${cx}" cy="${cy}" r="${MR+6}" class="mring"/><text x="${cx}" y="${cy+34}" text-anchor="middle" class="mglyph">§</text></g>`;
  s+=`<text x="${cx}" y="${cy+MR+34}" text-anchor="middle" class="mlabel">${esc(st.n)}</text></svg>`;return s;}
function stationBrief(st){const m=st.img&&IMG[st.img]?IMG[st.img]:null;const entries=ATLAS.filter(a=>a.st.includes(st.id)).sort((a,b)=>(a.st[0]===st.id?0:1)-(b.st[0]===st.id?0:1));
  return `<div class="sbrief">${m?`<a href="#" class="spic" data-lb="${st.img}" style="background-color:${m.avg}"><img src="img/${st.img}.jpg" alt="${esc(m.a+', '+m.t)}" style="object-position:${m.fp}" loading="lazy"></a>`:`<div class="spic plate"><div class="rwm" style="font-size:120px">§</div></div>`}<div class="stxt"><div class="label cap">${esc(st.k)}</div><h3>${esc(st.n)}</h3><p>${esc(st.brief)}</p><div class="srow"><span class="l">Money</span><span>${esc(st.money)}</span></div><div class="srow"><span class="l">First check</span><span>${esc(st.check)}</span></div>${st.cap?`<div class="scap">${st.x?'':'Illustration: '}${esc(st.cap)}</div>`:''}<div class="chips" style="margin-top:12px">${entries.slice(0,6).map(a=>`<button class="tag" data-under="${a.id}">${esc(a.t)}</button>`).join('')}${entries.length>6?`<button class="tag" data-filter="${st.id}">all ${entries.length} →</button>`:''}</div></div></div>`;}
function selectStation(id,scroll){if(!UST(id))return;stationSel=id;$('#ring').innerHTML=ringSVG();bindRing();bindLightbox($('#ring'));$('#sbrief').innerHTML=stationBrief(UST(id));bindLightbox($('#sbrief'));bindUnderLinks($('#sbrief'));$$('#sstrip .sst').forEach(b=>b.classList.toggle('on',b.dataset.station===id));if(scroll){const b=$(`#sstrip .sst[data-station="${id}"]`);if(b&&b.scrollIntoView)try{b.scrollIntoView({block:'nearest',inline:'center',behavior:'smooth'});}catch(e){}}}
function bindRing(){$$('#ring .stn').forEach(g=>{g.addEventListener('click',()=>selectStation(g.dataset.station,true));g.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();selectStation(g.dataset.station,true);}});});}
function stationStrip(){return STATIONS.map(st=>{const m=st.img&&IMG[st.img]?IMG[st.img]:null;return `<button class="sst ${st.id===stationSel?'on':''}" data-station="${st.id}">${m?`<img src="img/t/${st.img}.jpg" alt="" loading="lazy" style="object-position:${m.fp}">`:'<span class="noimg">§</span>'}<span class="n">${esc(st.n)}</span><span class="k">${esc(st.k)}</span></button>`;}).join('');}

/* ---- atlas ---- */
let atlasFilter='all',atlasQ='';
function atlasRows(){const q=atlasQ.toLowerCase();return ATLAS.filter(a=>(atlasFilter==='all'||a.st.includes(atlasFilter))&&(!q||(a.t+' '+a.b+' '+a.c).toLowerCase().includes(q)));}
function drawAtlas(){const rows=atlasRows();$('#atlist').innerHTML=rows.map(a=>`<button class="atl" data-under="${a.id}"><span class="at"><b>${esc(a.t)}</b>${a.kind==='case'?`<i class="yr">${a.year}</i>`:''}</span><span class="ab">${esc(firstSentence(a.b))}</span><span class="ac">Check: ${esc(a.c)}</span><span class="af">${vflag(a.v)}${a.st.map(s=>`<span class="tag">${esc(stName(s))}</span>`).join('')}</span></button>`).join('')||'<div class="empty">Nothing matches.</div>';bindUnderLinks($('#atlist'));bindTips($('#atlist'));$('#atcount').textContent=`${rows.length} of ${ATLAS.length}`;$$('#atfilters .tag').forEach(b=>b.classList.toggle('on',b.dataset.filter===atlasFilter));}
function openAtlas(id){const a=ATL(id);if(!a)return;const story=a.story&&STORIES.find(s=>s.id===a.story);const m=a.img&&IMG[a.img]?a.img:null;
  openDrawer(esc(a.t),`${a.kind==='case'?`<span class="tag">${a.year}</span> `:''}${vflag(a.v)} ${a.st.map(s=>`<button class="tag" data-station-go="${s}">${esc(stName(s))}</button>`).join('')}`,
   `${m?figure(m,a.x?'':'Illustration; the work pictured is public domain.')+'<div style="height:14px"></div>':''}<div class="quote">${esc(a.b)}</div><div class="sec" style="margin-top:16px"><span class="label cap">What to check</span><p style="margin:6px 0 0;font-size:15px">${esc(a.c)}</p></div>${story?`<div class="sec"><span class="label cap">In the Salon</span><div style="margin-top:6px"><button class="btn sm" data-story="${esc(story.id)}">${esc(story.t)}</button></div></div>`:''}<div class="sec"><span class="label cap">Sources</span>${srcList(a.src)}</div><div class="sec"><button class="btn sm copy" data-v="${esc(location.href.split('#')[0]+'#under-'+a.id)}">Copy link</button></div>`);
  bindTips($('#dBody'));$$('#dSub [data-station-go]').forEach(b=>b.addEventListener('click',()=>{closeDrawer();go('undertow');selectStation(b.dataset.stationGo,true);atlasFilter=b.dataset.stationGo;drawAtlas();scrollToEl($('#ring'));}));setHash('under-'+a.id);}
function bindUnderLinks(root){$$('[data-under]',root).forEach(b=>{if(b.__u)return;b.__u=1;b.addEventListener('click',e=>{e.stopPropagation();openAtlas(b.dataset.under);});});$$('[data-filter]',root).forEach(b=>{if(b.__f)return;b.__f=1;b.addEventListener('click',e=>{e.stopPropagation();atlasFilter=b.dataset.filter;drawAtlas();if(!b.closest('#atfilters'))scrollToEl($('#atlist'));});});}

/* ---- checks ---- */
function drawChecks(){const done=store.get('under.checks',[]);$('#checks').innerHTML=CHECKS.map((c,i)=>`<div class="chk ${done.includes(i)?'done':''}"><label><input type="checkbox" data-i="${i}" ${done.includes(i)?'checked':''}><span class="k">${i+1}</span><span class="t">${esc(c[0])}</span></label><button class="lnk" data-under="${c[1]}">why</button></div>`).join('');$('#chkprog').textContent=`${done.length} of ${CHECKS.length}`;
  $$('#checks input').forEach(el=>el.addEventListener('change',()=>{const d=new Set(store.get('under.checks',[]));el.checked?d.add(+el.dataset.i):d.delete(+el.dataset.i);store.set('under.checks',[...d]);drawChecks();}));bindUnderLinks($('#checks'));}

function renderUndertow(){const el=$('#v-undertow');const cases=ATLAS.filter(a=>a.kind==='case').sort((a,b)=>b.year-a.year);
  el.innerHTML=`<div class="head"><div><h1>Undertow</h1><p class="dek">The machinery under the price: who takes what from a hammer, how a picture moves through galleries, freeports, loans, trusts and borders, and the cases that show what goes wrong. Every number links a source; what could not be verified is marked.</p></div></div>
  <div class="grid">
  <div class="sect c12"><div class="rh"><h2>Follow the money</h2><span class="sub">move the hammer, change the room, add a guarantee: the ribbons show where every dollar goes</span></div><div id="fctl"></div><div class="plate sankwrap" style="margin-top:14px"><div id="fsank"></div></div><div class="tblwrap sensw" id="fsens"></div><div class="note sensnote">Each column reruns the model with only the hammer changed. A third-party guarantee stays at its dollar amount: below it the irrevocable bidder buys the work at the bid, so the hammer cannot fall under it.</div><div class="kpis" id="fkpi" style="margin-top:14px"></div><p class="note" id="ffx"></p><div class="ledacts"><span class="label cap">The ledger, line by line</span><span class="acts"><button class="btn sm" id="fCopy">Copy the ledger</button><button class="btn sm" id="fCsv">Download CSV</button></span></div><div class="tblwrap" id="fledger"></div><div class="rh" style="margin-top:22px"><h2>Compare the rooms</h2><span class="sub">the same picture bought in five cities</span></div><div class="tblwrap" id="fcompare"></div><div class="rh" style="margin-top:22px"><h2>Compare the destinations</h2><span class="sub">the same purchase, kept in different places</span></div><div class="tblwrap" id="fdests"></div><div class="rh" style="margin-top:22px"><h2>Where to buy, where to keep</h2><span class="sub">every room against every destination: the first year in all</span></div><div id="fmatrix"></div></div>
  <div class="sect c12"><div class="rh"><h2>Journeys</h2><span class="sub">how a picture and its money moved, hand to hand, city to city</span></div><div class="journeys">${JOURNEYS.map(journeyCard).join('')}</div></div>
  <div class="sect c7"><div class="rh"><h2>The circuit</h2><span class="sub">sixteen stations a work passes through; choose one</span></div><div id="ring" class="ringwrap"></div><div id="sstrip" class="sstrip">${stationStrip()}</div></div>
  <div class="sect c5"><div class="rh"><h2>At this station</h2><span class="sub">what happens, what money does, what to ask</span></div><div id="sbrief"></div></div>
  <div class="sect c12"><div class="rh"><h2>The atlas of undercurrents</h2><span class="sub"><span id="atcount"></span> entries · <input id="atq" type="search" placeholder="Filter the atlas" aria-label="Filter the atlas" style="width:170px;padding:5px 9px"></span></div><div class="chips" id="atfilters"><button class="tag" data-filter="all">All</button>${STATIONS.map(s=>`<button class="tag" data-filter="${s.id}">${esc(s.n)}</button>`).join('')}${Object.keys(THEMES).map(t=>`<button class="tag" data-filter="${t}">${esc(THEMES[t])}</button>`).join('')}</div><div id="atlist" class="atlist"></div></div>
  <div class="sect c7"><div class="rh"><h2>Casebook</h2><span class="sub">the frauds, cartels, seizures and rulings, newest first</span></div><div class="cases">${cases.map(a=>`<button class="case" data-under="${a.id}"><span class="y">${a.year}</span><span class="t"><b>${esc(a.t)}</b><small>${esc(firstSentence(a.b))}</small></span><span class="f">${vflag(a.v)}</span></button>`).join('')}</div></div>
  <div class="sect c5"><div class="rh"><h2>Ten checks before any deal</h2><span class="sub"><span id="chkprog"></span> · <button id="chkcopy">copy as text</button></span></div><div id="checks"></div><div class="note" style="margin-top:12px">Ticks are saved in this browser only. Each check links the atlas entry it comes from.</div></div>
  </div>`;
  $('#fCopy').addEventListener('click',()=>copyText(flowLedgerText(),$('#fCopy')));$('#fCsv').addEventListener('click',()=>offerFile(`subhasta-follow-the-money-${TODAY}.csv`,flowLedgerCSV(),'CSV'));
  presetFlowFromLens();initFlow();bindLightbox(el);bindLinks(el);selectStation(stationSel);$$('#sstrip .sst').forEach(b=>b.addEventListener('click',()=>selectStation(b.dataset.station,false)));
  $('#atq').addEventListener('input',e=>{atlasQ=e.target.value;if(atlasQ&&atlasFilter!=='all'){atlasFilter='all';}drawAtlas();});bindUnderLinks($('#atfilters'));drawAtlas();bindUnderLinks($('.cases',el));
  bindTips(el);drawChecks();$('#chkcopy').addEventListener('click',()=>copyText('Ten checks before any deal (Subhasta)\n'+CHECKS.map((c,i)=>`${i+1}. ${c[0]}`).join('\n')));}

/* does the artist's resale right run in this room in this year? The term: ARTIST_DIED null = living, a year = died then (the right runs to
   the end of the 70th year after), false or unknown = no right (an object, not an artist's work). The person: a national of a country the
   UK and French rights pay (ARTIST_NATION in ARR_NATIONS; an artist not in the map is assumed to qualify). The room: it must have the right. */
const arrInTerm=(artist,y)=>{const v=ARTIST_DIED[artist];return v===null||(typeof v==='number'&&y-v<=70);};
const arrQualifies=artist=>{const n=ARTIST_NATION[artist];return !n||ARR_NATIONS.includes(n);};
const arrApplies=(artist,y,venue)=>arrInTerm(artist,y)&&arrQualifies(artist)&&(!venue||!!(VENUES[venue]&&VENUES[venue].arr));
/* the sale room a RESULTS city maps to, through VENUES[].cities; New York when the city is none of the five rooms (online, Stuttgart, Dallas…) */
const venueForCity=city=>Object.keys(VENUES).find(k=>(VENUES[k].cities||[]).includes(city))||'ny';
/* the lot replayed as a purchase today: today's schedule on the implied hammer, and the resale right by the artist's term and nationality now */
function flowForLot(r){if(!r)return;const h=SCHED[r.house]?r.house:'sothebys';const total=r.price*1e6;const hammer=impliedHammer(h,total);const venue=venueForCity(r.city);const living=arrApplies(r.artist,+TODAY.slice(0,4),venue);
  Object.assign(FLOW,{hammer:Math.round(hammer/1000)*1000,house:h,venue,structure:'third',guar:.85,feeShare:.2,seller:total>50e6?'0':'5',dest:VENUES[venue].homeDest,living,artist:ARTIST_DIED[r.artist]===undefined?null:r.artist,imported:false,ship:Math.max(5000,Math.round(total*0.0005/1000)*1000),loan:'none',ins:.002,touched:true});
  go('undertow');initFlow();toast(`${r.artist}, ${r.title}: implied hammer ${fmtUSD(FLOW.hammer)}`);window.scrollTo({top:0});}
